	title 'QD UTILS             GS ROM 2.0'*****************************************************************			   **              UTILS		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	string asis	blanks off	include 'all.macros'		MACRO&lab	BumpLongBy2 &adr&lab	lda &adr	ldx &adr+2	inc a	bne @1	inx@1	inc a	bne @2	inx@2	sta &adr	stx &adr+2	MEND			include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyEC0	IMPORT BusyEC4	IMPORT EndCall12	IMPORT EndCall4	IMPORT EndCall8	IMPORT QDStart	IMPORT oEndCall12;                COPY UTILS/UTILS****************************************************************** Utilities for the	Core Routines*********************************************************************************************************************************** SetRect (RPtr : ptr; Left,Top,Right,Bottom : integer)** This is a glue routine in QuickDraw that for Pascal takes* four integers off	the stack and puts them in a rectangle.*****************************************************************	EXPORT SetRectSetRect	PROCRTL1	equ 1RTL2	equ RTL1+3Bottom	equ RTL2+3Right	equ Bottom+2Top	equ Right+2Left	equ Top+2RPtr	equ Left+2	tsc	; get stack	phd	; save d	tcd	; set stack to zp	lda Top	sta [RPtr]	ldy #2	lda Left	sta [RPtr],y	iny	iny	lda Bottom	sta [RPtr],y	iny	iny	lda Right	sta [RPtr],y	jmp EndCall12	ENDP****************************************************************** OffsetRect (RPtr : ptr; dh, dv : integer);*****************************************************************	EXPORT OffsetRectOffsetRect	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3OffsetY	equ RTL2+3OffsetX	equ OffsetY+2PointerToRect	equ OffsetX+2	tsc	; get stack	phd	; save direct	tcd	; set direct to stack	ldy #6Loop	lda [PointerToRect],y	clc	adc OffsetX	sta [PointerToRect],y	dey	dey	lda [PointerToRect],y	clc	adc OffsetY	sta [PointerToRect],y	dey	dey	bpl Loop	jmp EndCall8	ENDP****************************************************************** InsetRect (RPtr :	ptr; dh, dv : integer);** Takes the rectange adds the point the	top/left and subracts* the point from the bottom right.*****************************************************************	EXPORT InsetRectInsetRect	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3OffsetY	equ RTL2+3OffsetX	equ OffsetY+2PointerToRect	equ OffsetX+2	tsc	; get stack	phd	; save direct	tcd	; set direct page to stack	lda [PointerToRect]	clc	adc OffsetY	sta [PointerToRect]	ldy #2	lda [PointerToRect],y	clc	adc OffsetX	sta [PointerToRect],y	iny	iny	lda [PointerToRect],y	sec	sbc OffsetY	sta [PointerToRect],y	iny	iny	lda [PointerToRect],y	sec	sbc OffsetX	sta [PointerToRect],y	jmp EndCall8	ENDP****************************************************************** SectRect (SrcAPtr, SrcBPtr : ptr; DestPtr : ptr) : boolean** Params*     input   long	  R1 Pointer*     input   long	  R2 Pointer*     input   long	  Result Pointer*     output  word?	  boolean** Calculates the intersection of R1 and	R2 and puts the* result in Result Rect*****************************************************************	EXPORT SectRectSectRect	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3ResultPointer	equ RTL2+3R2Pointer	equ ResultPointer+4R1Pointer	equ R2Pointer+4Result	equ R1Pointer+4	tsc	; get stack	phd	; save direct	tcd	; set direct to stack	ldy #2Loop1	lda [R1Pointer],y	; compare the two top/left points	cmp [R2Pointer],y	; take larger	bpl GotLarger	lda [R2Pointer],yGotLarger	sta [ResultPointer],y	dey	dey	bpl Loop1	ldy #6Loop2	lda [R1Pointer],y	; compare the two bot/right points	cmp [R2Pointer],y	bmi GotSmaller	lda [R2Pointer],yGotSmaller	sta [ResultPointer],y	dey	dey	cpy #3	bpl Loop2	ldy #4	lda [ResultPointer]	cmp [ResultPointer],y	bpl ABadRect	dey	dey	lda [ResultPointer],y	ldy #6	cmp [ResultPointer],y	bpl ABadRect	lda #TRUE	; put true in a-regAllDone	sta Result	jmp EndCall12ABadRect	lda #FALSE	; zero the dest rect	ldy #6Loop4	sta [ResultPointer],y	dey	dey	bpl Loop4	bra AllDone	; A-reg has false flag	ENDP****************************************************************** UnionRect (SrcAPtr, SrcBPtr : ptr; DestPtr : ptr)** Params*     input      long     R1 Pointer*     input      long     R2 Pointer*     input      long     Result Pointer** Calculates the union of R1 and R2 and	puts the* result in Result Rect*****************************************************************	EXPORT UnionRectUnionRect	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3ResultPointer	equ RTL2+3R2Pointer	equ ResultPointer+4R1Pointer	equ R2Pointer+4	tsc	; get stack	phd	; save direct register	tcd	; set direct to stack	ldy #2Loop1	lda [R1Pointer],y	; compare the two top/left points	cmp [R2Pointer],y	; and keep the smaller one	bmi GotSmaller	lda [R2Pointer],yGotSmaller	sta [ResultPointer],y	dey	dey	bpl Loop1	ldy #6Loop2	lda [R1Pointer],y	; compare the two bot/right points	cmp [R2Pointer],y	; and keep the bigger one	bpl GotBigger	lda [R2Pointer],yGotBigger	sta [ResultPointer],y	dey	dey	cpy #3	bpl Loop2	jmp EndCall12	ENDP****************************************************************** PtInRect ( PPtr :	ptr; RPtr: ptr) : boolean** Params*     input     long    R  Pointer*     input     long    P  Pointer*     output    word?   boolean** Determines if Point is in rectangle* result in Result Rect** Modification History**   27 May 86  The test for the Y value	of the point*              being less than the bottom used a BCS*              instead of a BPL.*****************************************************************	EXPORT PtInRectPtInRect	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3RectPtr	equ RTL2+3PtPtr	equ RectPtr+4Result	equ PtPtr+4	tsc	; get stack	phd	; save direct	tcd	; set direct to stack	lda [PtPtr]	cmp [RectPtr]	bmi BadPoint	ldy #4	cmp [RectPtr],y	bpl BadPoint	; signed compare on	27 May 86	dey	dey	lda [PtPtr],y	cmp [RectPtr],y	bmi BadPoint	ldy #6	cmp [RectPtr],y	bpl BadPoint	lda #TRUEAllDone	sta Result	jmp EndCall8BadPoint	lda #FALSE	bra AllDone	ENDP****************************************************************** Pt2Rect (PtAPtr, PtBPtr : Ptr; RPtr :	Ptr);**      input     long     Ptr to PtA*      input     long     Ptr to Ptb*      input     long     Ptr to Result	Rect** This is another QuickDraw routine that is glue for Pascal.*****************************************************************	EXPORT Pt2RectPt2Rect	PROCRTL1	equ 1RTL2	equ RTL1+3RPtr	equ RTL2+3BPtr	equ RPtr+4APtr	equ BPtr+4	tsc	; get stack	phd	; save d	tcd	; set stack to zp	lda [APtr]	; get y of point a	sta [RPtr]	; put it in rect	ldy #2	; get x of point a	lda [APtr],y	; put it in rect	sta [RPtr],y	;	lda [BPtr],y	; get X of point b	ldy #6	; put it in rect	sta [RPtr],y	;	lda [BPtr]	; get Y of point b	dey	dey	sta [RPtr],y	; put it in rect	jmp EndCall12	ENDP****************************************************************** PtToAngle** This is a weird QuickDraw call handy to use with arcs and* wedges, which Cary Clark thinks we should not support.*********************************************************************************************************************************** EqualRect   (r1Ptr,r2Ptr : ptr) : boolean;** Params*     input      long    R1 Pointer*     input      long    R2 Pointer*     output     word?   boolean** Determines if two	rectangles are equal* result in Result Rect*****************************************************************	EXPORT EqualRectEqualRect	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3R1Ptr	equ RTL2+3R2Ptr	equ R1Ptr+4Result	equ R2Ptr+4	tsc	; get stack	phd	; save direct	tcd	; transfer stack to	direct	ldy #6Loop	lda [R1Ptr],y	cmp [R2Ptr],y	bne NotEqual	dey	dey	bpl Loop	lda #TRUE	; put true in a-regAllDone	sta Result	jmp EndCall8NotEqual	lda #FALSE	; zero the dest rect	bra AllDone	ENDP****************************************************************** NotEmptyRect (RPtr : Ptr) : boolean;** Params*     input     long    Rect Pointer*     output    word?   boolean** Determines if rectangle is empty.  Empty is defined by* the top/left being greater than or equal to the bot/right.** Modification History** 31 Dec 86    SEG**    Was returning true when not empty and false when empty	instead*    of right way.** 05 Feb 87    SEG**    Making this call match the specification caused software*    to stop working.  We now redefine the call to be**	 NotEmptyRect**    It returns true when the rect is not empty and false if it*    is empty.*****************************************************************	EXPORT NotEmptyRectNotEmptyRect	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3RPtr	equ RTL2+3Result	equ RPtr+4	tsc	; get stack	phd	; save direct	tcd	; set direct to stack	ldy #0Loop	lda [RPtr],y	iny	iny	iny	iny	cmp [RPtr],y	bpl YesEmpty	dey	dey	cpy #4	bcc Loop	lda #TRUE	; put true in a-regAllDone	sta Result	jmp EndCall4YesEmpty	lda #FALSE	bra AllDone	ENDP******************************************************************* Function Random :	Integer**  Basically, this is a transliteration	of the 68000 random	function in*  QUICKDRAW done by Bill Atkinson.**  REF:*      "A More portable FORTRAN Random Number Generator"*      by Linus Schrage*      ACM Transactions on Mathematical	Software*      Volume 5, No. 2, June 1979, Pages 132-138************************** get low 16 bits of seed and form low product* XALO:= A * LoWord(seed)************************	EXPORT RandomRandom	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Result	equ RTL2+3	jsr QDStart	tdc	clc	adc #256	; we only use the high page	tcd	pha	; space for result	pha	PushWord RandSeed	; LoWord(seed)     {multiplier}	PushWord #16807	; A=7**5           {multiplicand}	_Multiply	; 1,S & 3,S = XALO {result}** Form 31 Highest bits of Low Product* FHI := HiWord(seed) * A + HiWord(XALO)*	pha	; space for result	pha	PushWord RandSeed+2	; HiWord(seed)     {multiplier}	PushWord #16807	; A=7**5           {multiplicand}	_Multiply	; 1,S & 3,S = PROD {result}*		 ; NOTE: XALO now at 5,S & 7,S*	lda 1,s	;        [PROD]	clc	adc 7,s	; plus   [XALO+2] {hiWord(XALO)}	sta 1,s	; equals [FHI]	lda 3,s	;        [PROD+2]	adc #0	; plus   0	sta 3,s	; equals [FHI+2]** Get Overflow past	31st bit of full product* K := FHI DIV 32768*	lda 1,s	;      [FHI]	clc	adc 1,s	; plus [FHI]	lda 3,s	;      [FHI+2]	adc 3,s	; plus [FHI+2]	tax	; equals K {store in X}*		; NOTE: use K as HiWord** Assemble all of the parts and pre-subtract P* Seed := (BitAnd(XALO,#0000FFFF)-P) + BitAnd(FHI,$00007FFF)*B16 +K*	lda 5,s	; [XALO]	sec	sbc #$FFFF	; minus P = #$7FFFFFFF	sta RandSeed	; temporarily	lda #0	sbc #$7FFF	sta RandSeed+2	lda 1,s	; [FHI]	and #$7FFF	clc	adc RandSeed+2	sta RandSeed+2	txa	; [K]	clc	adc RandSeed	sta RandSeed** If seed < 0 then seed + P*	lda RandSeed+2	bpl Update	lda RandSeed	clc	adc #$FFFF	sta RandSeed	lda RandSeed+2	adc #$7FFF	sta RandSeed+2Update	lda RandSeed	; this is the result	cmp #$8000	; use 0 if -32768	bne NumOK	lda #0NumOK	plx	;get rid of extra stack stuff	plx	plx	plx	sta Result,S	; result	jmp BusyEC0	ENDP****************************************************************** SetRandSeed     (Value : Long Integer)*****************************************************************	EXPORT SetRandSeedSetRandSeed	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Value	equ RTL2+3	jsr QDStart	ldx #256	lda Value,s	sta RandSeed,x	lda Value+2,s	sta RandSeed+2,x	jmp BusyEC4	ENDP****************************************************************** AddPt   (SrcPtPtr	: Ptr; DestPtPtr : ptr);*****************************************************************	EXPORT AddPtAddPt	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3DestPtPtr	equ RTL2+3SrcPtPtr	equ DestPtPtr+4	tsc	; get stack	phd	; save direct	tcd	; and so on...	ldy #2Loop	lda [SrcPtPtr],y	clc	adc [DestPtPtr],y	sta [DestPtPtr],y	dey	dey	bpl Loop	jmp EndCall8	ENDP****************************************************************** SubPt   (SrcPtPtr	: Ptr; DestPtPtr : ptr);*****************************************************************	EXPORT SubPtSubPt	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3DestPtPtr	equ RTL2+3SrcPtPtr	equ DestPtPtr+4	tsc	; get stack	phd	; save direct	tcd	; and so on...	ldy #2Loop	lda [DestPtPtr],y	sec	sbc [SrcPtPtr],y	sta [DestPtPtr],y	dey	dey	bpl Loop	jmp EndCall8	ENDP****************************************************************** SetPt (PPtr : ptr; h,v integer);** Parameters*      input     long     PPtr*      input     word     h*      input     word     v** This is one of the glue routines used	by* pascal programers.*****************************************************************	EXPORT SetPtSetPt	PROCRTL1	equ 1RTL2	equ RTL1+3V	equ RTL2+3H	equ V+2PPtr	equ H+2	tsc	; get stack	phd	; save d	tcd	; set stack to zp	lda V	sta [PPtr]	ldy #2	lda H	sta [PPtr],y	jmp EndCall8	ENDP****************************************************************** EqualPt (p1ptr,p2ptr : ptr) : boolean** Params*      input     long   P1 Pointer*      input     long   P2 Pointer*      output    word?  boolean*****************************************************************	EXPORT EqualPtEqualPt	PROC*              using CoreDATARTL1	equ 1RTL2	equ RTL1+3P1Ptr	equ RTL2+3P2Ptr	equ P1Ptr+4Result	equ P2Ptr+4	tsc	phd	tcd	ldy #2Loop	lda [P1Ptr],y	cmp [P2Ptr],y	bne NotEqual	dey	dey	bpl Loop	lda #TRUEReportResult	sta Result	jmp EndCall8NotEqual	lda #FALSE	bra ReportResult	ENDP****************************************************************** LocalToGlobal  (PPtr : Ptr);** Params*      input      long    P Pointer** Modifications**     April 7, 1986	   Makes BusyEC4 call to terminate*****************************************************************	EXPORT LocalToGlobalLocalToGlobal	PROC*              using CoreDATAOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPtr	equ RTL2+3	jsr QDStart	lda PPtr,s	tax	lda PPtr+1,s	phb	;save bank	pha	plb	plb	; set bank	lda |0,x	sec	ldy #o_BoundsRect	sbc [PortRef],y	sta |0,x	lda |2,x	sec	iny	iny	sbc [PortRef],y	sta |2,x	plb	; restore bank	jmp BusyEC4	ENDP****************************************************************** GlobalToLocal (PPtr : Ptr);** Params*       input     long   P Pointer** Modifications**     April 7, 1986	   Makes BusyEC4 call to terminate*****************************************************************	EXPORT GlobalToLocalGlobalToLocal	PROC*              using CoreDATAOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPtr	equ RTL2+3	jsr QDStart	lda PPtr,s	tax	lda PPtr+1,s	phb	;save bank	pha	plb	plb	; set bank	lda |0,x	clc	ldy #o_BoundsRect	adc [PortRef],y	sta |0,x	lda |2,x	clc	iny	iny	adc [PortRef],y	sta |2,x	plbAllDone	jmp BusyEC4	ENDP****************************************************************** GetPixel (Hor, Vert : integer) : integer*****************************************************************	EXPORT GetPixelGetPixel	PROC*              using CoreDATA*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Vert	equ RTL2+3Hor	equ Vert+2Result	equ Hor+2	jsr QDStart	jsl PortLoc2ZP	; get port stuff;---------------------------------------------------;; Convert Vert to global coordinates and multiply; by width.	pha	; space for result	pha	lda Vert+4,s	sec	sbc BoundsRect	pha	lda Width	pha	_Multiply;---------------------------------------------------;; Leave the result on the stack a minute and convert; horizontal coordinates to global and then to a; byte number.;	lda Hor+4,s	sec	sbc BoundsRect+2	lsr a	; convert to byte number	bit PortSCB-1	bpl Mode320	lsr aMode320	clc	adc 1,s	; add to Vert * Width	tay	; put in y	pla	; pull result of earlier multiply	pla	; off the stack;---------------------------------------------------;; Now we have index	to byte in pixel map in y. We; must figure how far we'll shift the resulting; byte to get desired pixel in lowest bits of; pixel.;	lda Hor,s	sec	sbc BoundsRect+2	bit PortSCB-1	bmi DoMode640;---------------------------------------------------;; For Mode320, the pixel is either odd or even.; If it is even we must shift it from the high nibble; to the low nibble.  If it is odd, we do not shift; it at all.;	and #1	; decide if odd or even	eor #1	; invert result	asl a	; double this so 1 becomes 2	bra ShiftIt	; go on and shift;---------------------------------------------------;; For Mode640, the pixel is in one of four positions:; zero thru three. If position is zero,	then must; shift it down three pixels (6 bits).	If it is three; we do not shift it.;DoMode640	and #3	eor #3ShiftIt	tax	lda [ImageRef],y	; get the byteShiftLoop	cpx #0	beq FinishIt	lsr a	lsr a	dex	bra ShiftLoopFinishIt	bit PortSCB-1	bpl MaskMode320	and #%00000011	bra PutResultMaskMode320	and #$0FPutResult	sta Result,s	jmp BusyEC4	ENDP;                COPY utils/scale****************************************************************** ScalePt**     PtPtr   : long*     SrcRectPtr : long*     DestRectPtr :	long***                 DestRectPtr^.Bottom -	DestRectPtr^.Top*     PtPtr^.v := --------------------------------------  *	PtPtr^.v*                 SrcRectPtr^.Bottom-SrcRectPtr^.Top**                 DestRectPtr^.Right - DestRectPtr^.Left*     PtPtr^.h := --------------------------------------  *	PtPtr^.h*                 SrcRectPtr^.Right-SrcRectPtr^.Left*******************************************************************	EXPORT ScalePtScalePt	PROCOrigDirect	equ 1AFlag	equ OrigDirect+2Sign	equ AFlag+2RTL1	equ Sign+2RTL2	equ RTL1+3DestRectPtr	equ RTL2+3SrcRectPtr	equ DestRectPtr+4PtPtr	equ SrcRectPtr+4	pea 0	; put this flag on stack to *		; indicate that this is first time thru	pea 0	; put this word on stack as indicator*		; of sign	phd	tsc	tcdLoop	lda #0	; make room for the	long divide result	pha	; needed later	pha	pha	pha	pha	; make room for multiply 	pha	ldy #4	lda [DestRectPtr],y	sec	sbc [DestRectPtr]	bpl NotNeg1	eor #$FFFF	inc a	inc SignNotNeg1	pha	lda [PtPtr]	bpl NotNeg2	eor #$FFFF	inc a	inc SignNotNeg2	pha	_Multiply;---------------------------------------; ; The stack looks like this;;        long (result of divide that we	are about to do);        word (hi word of mulitply result);        word (low word of multiply result);        tos	ldy #4	lda [SrcRectPtr],y	sec	sbc [SrcRectPtr]	bpl NotNeg3	eor #$FFFF	inc a	inc SignNotNeg3	pea 0	pha	_LongDivide	pla	; this is result we	want	plx	; these are all ignored	plx	plx	lsr Sign	; if Sign is 1 or 3	then have	bcc Even	; odd number of negative numbers	eor #$FFFF	; so result is negative.  if Sign	inc a	; is 0 or 2 then have even number of*		; neg numbersEven	sta [PtPtr]	lda AFlag	bne AllDone	dec AFlag	; next time we'll fall thru	BumpLongBy2 PtPtr	; bump these pointers so same code	BumpLongBy2 SrcRectPtr ; works with H.	BumpLongBy2 DestRectPtr	stz Sign	; reset sign	jmp LoopAllDone	pld	pla	; pull off flag word	pla	; pull off sign word	jmp oEndCall12	ENDP	END